globalThis.CRPGLocalStory={"version":1,"episodes":{"ISK_L01_K_016":{"title":"객잔 아래의 협객들","before":[["행추","중운, 저쪽 받침을 부탁해. 나는 올라가겠어!"],["중운","잠깐, 사람을 구할 때까지는 멋있는 대사 하지 마!"],["나","내 몫은? 구경꾼은 좀 미안한데, 올라가면 구조할 사람이 늘 것 같아."],["행추","그럼 아래를 맡아 줘. 난 행추야. 저 친구는 중운. 소개가 좀 흔들리네!"],["","둘은 익숙하게 자리를 나눴다. 나는 끊어질 듯 팽팽한 줄을 피해 쐐기를 찾았다. 받침 아래 박힌 부러진 상자를 먼저 치워야 했다."]],"steps":[{"kind":"DESTROY","map":null,"title":"받침목이 들어갈 자리","prompt":"승강기 아래의 부서진 짐짝을 제거한다. 줄과 사람을 공격하는 것이 아니다.","result":"받침목을 밀어 넣을 공간이 생겼다."}],"after":[["중운","행추, 네 책 떨어졌다. 사람부터 받치고 있으니까 내가 주울게."],["행추","고마워. 하지만 그건 너한테 빌린 책인데."],["중운","그러니까 나중에 주우라고! 지금은 양손 써!"],["나","소개는 잘 들었어. 두 사람 평소에도 이래? 대답은 내려온 다음에 해 줘!"]],"choices":[]},"ISK_L01_AA_004":{"title":"수레보다 빠른 입","before":[["호두","천! 천 잡아! 내 모자는 다음에 구해도 돼!"],["중운","당주, 앞을 막으면 같이 깔려! 바퀴 쪽으로 돌려!"],["호두","좋은 생각이야! 손도 같이 빌려주면 더 좋고!"],["나","두 사람 아는 사이면 싸움은 나중에! 나 이 천하고 처음 만났는데 벌써 지고 있어!"],["","중운이 바퀴를 떠받쳤다. 나는 옷자락이 낀 덧판을 보았다. 저것만 깨면 수레꾼을 끌어낼 수 있었다."]],"steps":[{"kind":"DESTROY","map":null,"title":"옷자락을 물고 있는 덧판","prompt":"사람과 바퀴를 피하고 부서진 덧판을 공격한다.","result":"덧판이 떨어져 나갔다. 당겨도 옷자락이 걸리지 않는다."}],"after":[["중운","사람은 빼낼 수 있겠어. 당주, 이번엔 정말 장례 얘기 하지 마."],["호두","알았어, 알았어. 살아서 집에 가는 손님한테까지 그러겠니?"],["중운","…인사는 이제야 하네. 난 중운, 퇴마사야. 당주와는 일 때문에 자주 부딪치는 사이고."],["나","반가워. 나는 방금까지 이 천하고 싸우다 진 사람이고."],["","호두는 웃으면서도 수레꾼에게서 눈을 떼지 않았다. 중운이 뒤를 받치자 그녀가 손을 뻗었다."]],"choices":[]},"ISK_L01_AB_019":{"title":"구조대의 저녁거리","before":[["향릉","누룽지, 불은 안 돼! 마른 뿌리야! 거기 있는 사람, 내가 줄 던질게!"],["각청","향릉? 약초 찾으러 이 비탈까지 온 거야?"],["향릉","그건 저분이고 나는 저녁거리! 설명은 끌어올린 다음에 해도 되지?"],["나","둘 다 끝내면 나도 그 저녁에 끼워 줘. 내가 내려가면 줄 길이가 모자랄 것 같아서."],["각청","위에서 발판을 골라 줘. 향릉, 줄 끝을 그 사람에게 넘겨."]],"steps":[{"kind":"SEARCH","map":null,"title":"발을 디딜 자리","prompt":"흔들리는 뿌리 대신 사람을 받칠 지점을 직접 확인한다.","result":"바위턱과 줄을 걸 나무를 확인했다. 각청에게 손짓했다.","clues":[{"id":"0","label":"부서진 흙턱","text":"손을 대자 흙이 떨어진다. 여기는 무게를 받지 못한다."},{"id":"1","label":"비스듬한 바위","text":"흙 밑으로 단단한 바위가 이어져 있다. 한 사람이 디딜 폭이다."},{"id":"2","label":"위쪽 나무","text":"뿌리가 비탈 반대쪽으로 뻗었다. 줄을 감아도 나무가 기울지 않는다."}]}],"after":[["향릉","난 향릉이야. 만민당에 오면 오늘보다 편하게 앉혀 줄게."],["각청","오늘은 약속보다 줄을 먼저 잡아."],["향릉","잡고 있어! 네 저녁도 챙겨 놓겠다는 말은 못 하게 하네."],["","각청은 대꾸 대신 줄을 두 번 당겼다. 나는 향릉과 발을 맞추고 몸을 뒤로 기울였다."]],"choices":[]},"ISK_L01_B_038":{"title":"짐이 먼저 알아본 선장","before":[["북두","다들 짐 내려! 갈대 뒤에 누가 기다린다. 우리를 마중 나온 얼굴은 아니네."],["가명","표행 짐도 이쪽으로 모을게! 선장님, 저 수레 하나만 빠지면 뒤가 열려!"],["나","가벼운 일부터 배우려고 왔는데 첫날부터 실전이네."],["가명","그럼 나랑 수레 맡자! 난 가명이야. 멈춰 있을 땐 인사도 해야지!"],["북두","인사는 움직이면서 해! 다친 사람 없이 지나가면 저녁은 내가 산다!"]],"steps":[{"kind":"ESCORT","map":"MAP_LY_DETAIL_DIHUA","title":"행렬을 돌다리까지","prompt":"습격자를 막고 수레를 안전한 곳으로 옮긴다. 방어 행동으로 수레의 피해를 줄일 수 있다.","result":"마지막 수레가 돌다리를 건넜다. 떨어진 짐도 다시 실었다."}],"after":[["가명","습격자들이 물러서고 있어! 그런데 저기, 수레 밑에 발이 낀 사람이 있어!"],["북두","남은 놈들은 내가 쫓아낸다. 너희는 사람부터 빼! 저녁은 그다음이다!"],["나","아직 안 끝났구나. 나도 뭐라도 할게."]],"choices":[]},"ISK_L01_K_105":{"title":"기억보다 먼저 남은 얼룩","before":[["연비","잠깐. 본인이 검사했다는 표식은 있는데, 검사는 한 적이 없다? 내가 잘못 들었으면 지금 끊어 줘."],["행추","틀림없이 흥미로운 사건이네. 사라진 기억과 남겨진 화물이라…"],["연비","책 제목은 사건 끝난 뒤에 지어. 지금 저분은 잘못한 게 없어도 일자리를 잃을 수 있어."],["행추","…그건 내가 가벼웠네. 비운 상회 쪽 인계 장소는 안내할 수 있어."],["나","좋아. 나는 사람 이름 외우는 것부터 할게. 연비, 맞지?"],["연비","응. 법률 자문을 하고 있어. 지금은 비용보다 현장이 사라지는 게 더 급해. 귀리 평원의 짐터부터 같이 보자."]],"steps":[{"kind":"SEARCH","map":"MAP_LY_DETAIL_GUILI","title":"한 번의 인계, 두 장의 접수표","prompt":"검사 전후의 짐과 원본 접수표를 비교한다.","result":"짐은 한 번 옮겨졌다. 병사가 직접 쓴 표가 남아 있지만 그는 그 부분만 기억하지 못했다.","clues":[{"id":"0","label":"수레의 빈 자리","text":"한 묶음을 내린 자리가 있다. 같은 짐을 두 번 내릴 공간은 없었다."},{"id":"1","label":"원본 접수표","text":"두 장 모두 같은 짐을 가리킨다. 두 번째 표에는 첫 검사의 흔적을 지우지 않은 채 새 시각만 적혀 있다."},{"id":"2","label":"인계인의 설명","text":"행추가 목격자를 따로 묻는다. 그는 짐을 한 번 받았고, 병사가 확인하는 것도 봤다고 답한다."}]}],"after":[["행추","증거를 모으면 단번에 풀릴 줄 알았는데, 물어볼 사람이 늘었군."],["연비","그래서 결말을 먼저 쓰면 안 된다는 거야. 이건 내가 맡아 둘게. 넌 아까 그 병사에게 해고된 건 아니라고 전해 줘."],["나","그 말은 내가 할게. 기다리는 입장이 얼마나 피곤한지 조금 알 것 같아서."]],"choices":[]},"ISK_L01_AA_034":{"title":"귀신보다 먼저 온 사람","before":[["중운","아까 병사에게서 사악한 기운은 느끼지 못했어. 그래도 더 살펴볼 수는 있어."],["호두","너만 가까이 가면 달아난 걸지도 모르지?"],["중운","지금 놀리는 거지."],["호두","절반은. 나머지 절반은 저 사람이 정말 무서워한다는 얘기야. 우린 자기 일을 하자."],["나","그럼 귀신 유무는 보류. 나는 바닥부터 볼게. 발밑 보는 건 자신 있어. 넘어져 봤거든."]],"steps":[{"kind":"SEARCH","map":null,"title":"목패가 돌아온 길","prompt":"수레와 목패가 실제로 어디를 거쳤는지 확인한다.","result":"목패의 홈과 수레에 남은 파편이 맞는다. 병사는 같은 수레를 다시 검사했다.","clues":[{"id":"0","label":"검사 목패","text":"홈 안에 붉은 나무 조각이 끼어 있다."},{"id":"1","label":"수레 난간","text":"나무가 막 깨진 자리가 있다. 목패의 파편과 결이 이어진다."},{"id":"2","label":"바퀴 주변","text":"줄을 벗어나 돌아온 자국은 없다. 수레는 이곳에 그대로 있었다."}]}],"after":[["중운","퇴마로 해결할 일이라고는 못 하겠어. 내가 모르는 걸 없다고 하기도 싫고."],["호두","그 말이면 됐어. 사람 앞에서 자신 없는 부적부터 붙이지 않는 퇴마사라니, 믿을 만하네."],["중운","칭찬인지 장난인지 하나만 해 줘."],["나","일단 칭찬으로 받아. 오늘 우리 셋 다 좀 지쳤잖아."]],"choices":[]},"ISK_L01_AB_069":{"title":"두 사람의 확인 방식","before":[["연비","각청, 그 확인서의 빈칸은 내가 볼게. 병사가 겁먹어서 서명부터 하려고 하잖아."],["각청","겁주려는 게 아니야. 뒤에 수레가 밀려 있어."],["연비","알아. 그래서 일을 두 번 하게 될 서명을 막는 거고. 손 빠른 건 네 장점인데 가끔 내 일까지 빠르게 만들어."],["나","그럼 나는 줄 뒤로 가 볼까? 여기서 똑똑한 척하면 나 때문에 세 번 하겠다."],["연비","그 전에 인사부터 할게. 난 연비, 법률 자문을 해. 각청이 데려온 사람이면 같이 움직여도 되겠지."],["각청","연비와 마지막 짐터를 봐 줘. 나는 줄부터 풀게."]],"steps":[{"kind":"SEARCH","map":"MAP_LY_DETAIL_GUILI","title":"주인이 없는 인수증","prompt":"귀리 평원의 인계 지점에서 문서와 실제 짐을 비교한다.","result":"서명이 없다고 인계가 없었던 것은 아니었다. 실물은 받는 사람에게 넘어갔지만, 이를 확인한 병사의 기억만 이어지지 않았다.","clues":[{"id":"0","label":"젖은 인수증","text":"작성 시각에는 잉크가 번졌지만, 서명 칸은 비어 있다."},{"id":"1","label":"천막 기둥","text":"비가 샌 자리에 짐을 옮긴 자국이 있다."},{"id":"2","label":"관리인의 답변","text":"관리인은 짐을 받았고 병사가 그 앞에 있었다고 답한다. 병사는 관리인을 부르지도 않았다고 기억한다."}]}],"after":[["연비","각청이 왜 널 데리고 왔는지 조금 알겠네. 모르는 걸 모른다고 말해 주는 사람이 필요했겠지."],["각청","돌아왔네. 이제 내 얘기는 그만하고 현장 얘기 해 줘."],["나","내 칭찬이었어. 조금만 더 듣고 싶었는데."]],"choices":[]},"ISK_L01_B_078":{"title":"선장의 말값","before":[["감우","선장님, 남십자 함대의 인계분을 확인하러 왔습니다. 수량이 두 번 올라와서요."],["북두","같은 짐을 두 번 받았다는 거야? 그럼 운임도 두 번 줘야겠네."],["감우","그렇게 계산되는 일은 아닙니다… 선장님도 아시잖아요."],["가명","지금 웃고 계셔도 짐은 다 살펴보셨어. 아까부터 세 번째야."],["감우","처음 뵙는 분이네요. 월해정에서 일하는 감우라고 합니다. 선장님과 함께 오셨나요?"],["나","응, 오늘 행렬에 끼어 온 사람이야. 나는 두 번째부터 손가락이 모자랐어. 감우 씨, 숫자 쪽은 부탁해도 돼?"],["감우","네. 대신 실제로 보신 순서만 알려 주세요. 제가 장부와 맞춰 보겠습니다."]],"steps":[{"kind":"SEARCH","map":null,"title":"둘로 적힌 한 묶음","prompt":"인계 전후 짐의 상태를 비교한다.","result":"한 묶음이 두 번 접수되어 있다. 물자는 늘지 않았고, 중간의 담당자만 기억이 비었다.","clues":[{"id":"0","label":"묶인 매듭","text":"같은 줄의 끝이 두 표에 모두 그려져 있다."},{"id":"1","label":"마른 받침","text":"짐은 내려놓은 자리에서 움직이지 않았다."},{"id":"2","label":"장부 두 장","text":"감우가 이름을 가리고 시각만 맞춘다. 같은 인계가 겹쳐 있다."}]}],"after":[["감우","선장님 말씀대로 짐은 하나였습니다. 이쪽 장부는 제가 정정하겠습니다."],["북두","운임 두 번은?"],["감우","한 번입니다."],["가명","대답은 진짜 빨라졌다."]],"choices":[]},"ISK_L02_K1_001":{"title":"아는 이야기의 빈자리","before":[["","송신의례라는 공고를 보여 주자 감우는 답 대신 반송된 보고통을 꺼냈다. 고운각의 경계대가 보낸 통이었다. 안에는 종이가 없었다."],["감우","처음 뵙겠습니다. 월해정 비서 감우입니다. 그 공고를 들고 찾아오신 분은 오늘 당신이 처음이네요."],["감우","의례의 이름은 제가 바꿀 수 없습니다. 다만 보고가 비었다고 이상이 없었다고 적을 수도 없어요. 제가 직접 확인하겠습니다."],["연비","수신 서명이 있는데 내용물이 없네. 배달한 사람부터 잘못했다고 몰리겠어. 나도 갈게."],["나","나도. 내가 아는 이야기가 맞는지 입으로만 떠들고 있었잖아. 이번엔 지금 일어난 걸 보러 가자."],["감우","두 분까지 나서실 일은…"],["연비","그 말은 보고통 찾아온 다음에 해. 네가 밤새 혼자 찾는 동안 우리 둘이 멀쩡히 쉬고 있기도 어렵거든."]],"steps":[{"kind":"SEARCH","map":"MAP_V141_GUYUN_WRECK","title":"해안 잔해의 보고통","prompt":"부서진 배에서 마지막으로 보낸 보고를 찾는다.","result":"보고통은 깨졌지만 밀랍 안의 종이는 남아 있었다. 바깥바다의 이상이 먼저 적혀 있다.","clues":[{"id":"0","label":"부러진 돛대","text":"부러진 방향이 물살과 반대다."},{"id":"1","label":"선체의 보고통","text":"보고통 뚜껑 안쪽에 종이가 말려 있다."},{"id":"2","label":"경계대 흔적","text":"경계대는 모닥불을 끄고 섬 안쪽으로 이동했다."}]},{"kind":"DEFEND","map":"MAP_V141_GUYUN_CHANNEL","title":"보고를 가져올 시간","prompt":"남쪽 항로의 적을 막아 경계대가 보고와 부상자를 옮기게 한다.","result":"경계대가 돌아왔다. 보고를 응광에게 전달할 수 있다."}],"after":[["","보고에는 항구 쪽으로 가던 무장한 배와 끊긴 경계선이 적혀 있었다. 이름이나 문장은 사라지지 않았다. 그걸 보낸 대원만 보고한 기억이 없었다."],["감우","원본은 제가 전달하겠습니다. 의례를 기다리는 동안에도 해안 경계는 바꿀 수 있으니까요."],["연비","대원의 서명부터 다시 받으라고 하진 마. 내가 본 회수 장소도 함께 붙여 줘."],["나","해안 경계를 바꾸고, 배를 확인하고. 좋아. 이제 내가 할 수 있는 말이 생겼네. 불길하다는 말 말고."]],"choices":[]},"ISK_L02_K2_001":{"title":"짐꾼의 끼니","before":[["","짐꾼은 같은 일을 두 번 했다는 확인 때문에 품삯을 받지 못했다. 그런데 그가 옮겼다는 자루에는 서로 다른 두 항구의 번호가 붙어 있었다."],["행추","우리 상회에 남은 인계표도 고운각에서 끊겨 있어. 네가 두 번 일했다는 말이 아니라, 한 짐을 두 곳에서 받았다는 말이군."],["향릉","그럼 짐꾼 아저씨가 거짓말한 건 아니잖아. 먼저 밥 먹고 얘기해. 오늘도 안 먹었지?"],["요요","향릉 언니 몫도 있어. 국물 맛본 건 식사로 안 셀 거야."],["향릉","아, 처음 보는 얼굴이다! 난 향릉, 만민당 요리사야. 이쪽은 요요."],["요요","안녕하세요, 요요예요. 향릉 언니가 밥부터 챙기라고 해서 따라왔어요."],["나","둘이 밥 맡으면 나는 짐표 맡을게. 다녀와서 또 세라고 하면 그땐 내가 화낼 거야."],["행추","연비에게도 원본을 봐 달라고 해 두겠네. 아저씨, 인사가 늦었습니다. 비운 상회의 행추입니다. 이번에는 짐의 주인도, 일한 사람도 빼놓지 않겠습니다."]],"steps":[{"kind":"SEARCH","map":"MAP_V141_GUYUN_WRECK","title":"잔해에 묶인 짐표","prompt":"고운각 해안에서 짐의 이동 흔적을 찾는다.","result":"같은 매듭의 자루를 찾았다. 살아남은 경계대가 나머지 짐을 옮겼다.","clues":[{"id":"0","label":"매듭 끝","text":"짐꾼이 고쳐 묶었던 방향과 같다."},{"id":"1","label":"긁힌 이름표","text":"이름은 지워졌다. 숫자와 무게만 남아 있다."},{"id":"2","label":"해안 발자국","text":"포대를 끌고 남쪽 항로로 이동한 흔적이 있다."}]},{"kind":"ESCORT","map":"MAP_V141_GUYUN_CHANNEL","title":"돌아갈 짐을 실은 배","prompt":"남쪽 항로의 경계대를 호위한다.","result":"인계받은 경계대와 원본 짐표를 배에 실었다. 짐꾼이 실제로 인계했다는 증언을 얻었다."}],"after":[["연비","이 짐은 실제로 인계됐어. 접수표가 둘이라고 네가 두 번 일했다는 뜻도, 거짓말했다는 뜻도 아니지. 내가 대조한 원본을 가져가."],["행추","항구 쪽 기록은 내가 맡지. 도장 하나 더 찍는 동안 저분 점심까지 식힐 순 없으니까."],["나","고마워. 이건 내가 전할게. 나중에 그 아저씨를 못 찾으면, 이번에는 짐 말고 사람부터 찾아 줘."]],"choices":[]},"ISK_L02_AA1_001":{"title":"아직 부르지 않은 이름","before":[["","호두는 구슬을 보여 준 날의 일을 종이에 적어 중운에게 내밀었다. 그는 마지막 줄에서 손을 멈췄다."],["중운","유해가 들어 있는데도 아무것도 느껴지지 않는다고? 직접 보고 싶지만, 함부로 열어 달라고 할 일은 아니네."],["호두","그래서 널 불렀어. 내 느낌만 믿고 이 사람한테 괜찮다고 해 버리면 안 되잖아."],["나","둘 다 모른다고 말해 주니까 오히려 좀 살 것 같네. 내가 설명을 못해서 혼자 이상한 사람이 된 줄 알았어."],["중운","나중에 안으로 들어가 확인할 일이 생기면 바깥은 내가 맡을게. 목소리만 듣고 따라가지 않도록 사람들을 붙잡아 둘 수는 있어."],["호두","그 약속은 받아 둘게. 귀신 안 나왔다고 출장비 깎지는 말고."],["중운","지금도 네 일을 공짜로 듣고 있는데."]],"steps":[],"after":[],"choices":[]},"ISK_L02_AA2_001":{"title":"잊어도 다시 적는 사람","before":[["","호두는 구슬을 열어 보자고 다시 묻는 대신 불복려에 증상부터 물었다. 백출은 치치가 받아 적은 병사의 말을 천천히 읽었다."],["백출","어서 오세요. 불복려의 백출입니다. 당주께서 말씀하신 분이 당신이군요. 이 아이는 우리 약방의 치치예요."],["치치","치치… 예요. 잊어버리지 않게, 적어 둘게요."],["백출","검사한 일을 잊은 것이지, 무엇을 검사하는지도 잊은 건 아니군요. 치치와 같은 증상이라고 부르지는 말아 주세요."],["치치","여기… 같은 질문. 두 번 했어요. 답은 달랐어요."],["호두","그 수첩을 믿어도 되겠지? 네가 내 이름 옆에 적어 둔 건 잠깐 접어 두고."],["치치","호두. 가까이 오지 않기. …여기는 안 접어요."],["나","내가 대신 받을게. 그 줄은 나도 잘 보이네."],["백출","알베도 씨께 연락하신다고 했죠. 이 기록도 보내세요. 물건을 열기 전에, 들고 있는 분에게 생기는 변화부터 확인해 달라고요."]],"steps":[],"after":[],"choices":[]},"ISK_L02_AB1_001":{"title":"무대 밖에서 맞춘 박자","before":[],"steps":[],"after":[],"choices":[]},"ISK_L02_AB2_001":{"title":"상자 밖의 거래","before":[["연비","젖으면 곤란하다고 증거를 그대로 비 맞힐 필요는 없어. 위치를 표시하고 덮자. 각청, 천 좀."],["각청","가져왔어. 저 사람은 네 의뢰인이야?"],["야란","구경하던 사람. 밤마다 저 상자를 찾는 짐꾼이 있다기에 흥미가 생겼거든."],["연비","구경꾼이 인계 시각까지 알고 있으면 보통 증인이 되지. 이름은?"],["야란","야란. 증인석은 편했으면 좋겠네."],["나","나도 끼워 줘. 의자는 내가 가져올게. 이번엔 앉아도 안 부서지는 걸로."]],"steps":[{"kind":"SEARCH","map":"MAP_LY_DETAIL_TIANQIU","title":"천주 골짜기의 빈 적재소","prompt":"야란이 본 짐꾼의 대기 장소를 확인한다.","result":"리월항 표식 위에 층암거연의 옛 광석 표식이 덧칠돼 있다.","clues":[{"id":"0","label":"말라 있는 덮개","text":"비가 온 뒤 걷어 낸 자국이다. 밤에 누군가 있었다."},{"id":"1","label":"상자 옆면","text":"새 표식 아래 오래된 광석 운반 표식이 비친다."},{"id":"2","label":"끊긴 인계표","text":"마지막 도착지는 없다. 계약서의 빈칸을 남겨 두고 이동시킨 짐이다."}]}],"after":[["연비","빈칸을 남겨 둔 이유는 내가 알아볼게. 야란, 의뢰받은 건 아니지?"],["야란","아직은. 네가 찾아낼 이름이 마음에 들면 달라질 수도 있고."],["각청","두 사람이 같은 일을 두 번 조사하지 않게 소식은 남겨 줘."],["나","그건 나도 부탁할게. 나는 같은 길을 두 번 걸을 체력이 없어."]],"choices":[]},"ISK_L02_B1_001":{"title":"전하지 못한 편지","before":[],"steps":[],"after":[],"choices":[]},"ISK_L02_B2_001":{"title":"배가 떠나기 전에","before":[],"steps":[],"after":[],"choices":[]},"ISK_L03_K1_031":{"title":"해안에서 반송된 보고","before":[["감우","각청 님, 고운각에서 가져온 보고와 같은 배가 다시 보였답니다. 경계대를 더 보내고 있습니다."],["각청","황금옥 확인과 해안 경계를 같이 진행해. 둘 중 하나가 끝날 때까지 기다리지 말고."],["연비","회수한 원본은 여기 있어. 이번에는 어느 시각부터 말이 달라졌는지 먼저 남기자."],["나","그 보고를 못 찾았으면 또 나만 아는 얘기로 끝났겠네. 이번에는 같이 움직여 줘서 고마워."]],"steps":[],"after":[],"choices":[]},"ISK_L03_K2_030":{"title":"이름 없는 짐표","before":[["행추","짐꾼은 아직 못 찾았어. 하지만 너와 함께 인계표를 가져온 건 내가 기억해. 그 일을 없었다고 하지는 못할 거야."],["연비","서류에는 이 사람과 짐꾼 둘 다 적혀 있어. 각청, 지금 기억이 안 난다는 이유로 목격까지 지우지는 말아 줘."],["각청","지우지 않아. 찾을 사람을 늘리겠어. 너는 선인께 무슨 말을 했는지 계속 설명해 줘."],["나","…응. 찾았다는 소식 오면 나부터 불러 줘. 그 사람 밥 먹었는지도 물어봐 주고."]],"steps":[],"after":[],"choices":[]},"ISK_L03_AA1_047":{"title":"문밖에 남긴 밧줄","before":[["중운","당주, 바깥 인원은 내가 맡을게. 안에서 목소리가 들려도 들어가지 말라고 전했어."],["호두","잘했어. 나 찾는 소리가 들려도 먼저 올라온 사람 얼굴부터 봐 줘."],["중운","그런 농담은…"],["호두","이번엔 농담 아니야."],["나","줄 두 번 당기면 멈추는 거지? 그냥 무서워서 잡아당겨도 혼내지 말아 줘."],["중운","혼내지 않아. 나도 끝을 놓지 않을게."]],"steps":[{"kind":"DESTROY","map":null,"title":"지하 계단의 낙석","prompt":"돌무더기를 치워 사람이 통과할 폭을 만든다. 검은 벽 안쪽을 무작정 공격하지 않는다.","result":"계단의 작은 낙석을 치웠다. 밧줄이 모서리에 걸리지 않는다."}],"after":[["호두","중운이 끝을 잡았으니까 이제 가자. 저 친구, 약속한 건 잘 지켜."],["나","그런 말은 들리는 데서 해 주면 안 돼?"],["중운","…들었어."],["호두","그러면 됐네! 우리 돌아올 때까지 부탁해."]],"choices":[]},"ISK_L03_AA2_077":{"title":"실험보다 먼저 할 일","before":[["알베도","백출이 보낸 기록에서는 물건을 옮긴 순간의 기억이 빠졌어. 하지만 네가 본 일은 그것만으로 설명되지 않아."],["나","그러니까 가방부터 열어서 답을 찾겠다는 건 아니지?"],["알베도","응. 먼저 네가 가까이 갔을 때와 내가 가까이 갔을 때를 비교할 거야. 치치가 적은 순서도 같은 기준으로 볼 수 있어."],["나","좋아. 돌아갈 길도 먼저 정하자. 실험하다 무서워지면 퇴근하겠다는 말은 해도 되지?"],["알베도","그걸 먼저 말해 줘. 기록보다 네가 돌아가는 게 우선이야."]],"steps":[{"kind":"SEARCH","map":"MAP_LY_DETAIL_MINGYUN","title":"접근하기 전의 물가","prompt":"현장과 퇴로를 확인한 다음 알베도에게 관찰을 시작하자고 말한다.","result":"기준점을 정했다. 먼저 주인공만 물가에 다가가 보고, 이상이 생기면 마른 돌까지 물러나기로 했다.","clues":[{"id":"0","label":"웅덩이 가장자리","text":"작은 원소 생물들이 움직이고 있다. 아직 가방 가까이로 다가오지 않았다."},{"id":"1","label":"마른 돌","text":"뒤로 물러설 수 있는 넓은 자리다. 알베도가 이곳에 표시를 남겼다."},{"id":"2","label":"관찰 기록","text":"치치의 수첩과 내 편지에는 빈 시간이 다르게 적혀 있다. 같은 현상이라는 결론부터 내리지 않기로 했다."}]}],"after":[["나","돌까지 물러나기, 혼자 가방 열지 않기. 외웠어. 혹시 내가 잊으면…"],["알베도","내가 말해 줄게. 그러니까 혼자 기억하려고 애쓰지 않아도 돼."],["","알베도가 먼저 물가 옆으로 비켰다. 나를 보는 자리와 돌아갈 길이 겹치지 않도록 했다."]],"choices":[]},"ISK_L03_AB1_021":{"title":"두 무대, 한 뒷문","before":[],"steps":[],"after":[],"choices":[]},"ISK_L03_AB2_074":{"title":"흔적을 남기는 침입자","before":[["야란","늦었네. 창고 안은 아직 건드리지 않았어. 바깥을 드나드는 사람만 셌지."],["다이루크","내가 오는 걸 기다렸나?"],["야란","아니. 들어갔다가 안 나오면 꺼내 줄 사람이 오길 기다렸지."],["각청","둘 다 혼자 들어갈 생각부터 하지 마. 출입구는 같이 확인할 거야."],["나","고마워. 나는 혼자 안 들어갈 생각을 벌써 세 번 했어."],["야란","좋은 판단이야. 그럼 나랑 바깥 흔적부터 보자."]],"steps":[{"kind":"SEARCH","map":"MAP_LY_DETAIL_CHASM_GATE","title":"옛 광석 창고의 바깥길","prompt":"층암거연 입구에서 창고로 향한 운송 흔적을 찾는다.","result":"들어간 짐은 있는데 나온 빈 수레가 없다. 창고 앞에서 다시 모이기로 했다.","clues":[{"id":"0","label":"광석 가루","text":"최근 바퀴 자국에 고운 검은 가루가 묻었다."},{"id":"1","label":"구겨진 통행표","text":"빈 수레로 나간다는 표시만 미리 찍혀 있다."},{"id":"2","label":"창고 방향의 바퀴 자국","text":"들어간 바퀴의 깊이가 돌아온 자국보다 깊다."}]}],"after":[["다이루크","연락을 남겨. 일이 틀어지면 밖에서 찾을 수 있어야 한다."],["야란","그 말, 자신한테도 하는 거지?"],["다이루크","…출입 시각을 적어 두지."],["나","방금은 야란이 이긴 걸로 할까? 아니, 그냥 적기만 할게."]],"choices":[]},"ISK_L03_B1_069":{"title":"거짓 목소리의 틈","before":[["케이아","선장, 나를 묶을 때도 이렇게 꽉 묶어야 하나?"],["북두","풀려서 두 번째 네가 나오면 어느 쪽을 골라야 할지 귀찮잖아."],["케이아","진짜를 알아볼 자신이 없다니 서운한데."],["나","둘 다 농담이 나오면 나 아직 살아 있는 거지? 밧줄은 더 조여도 돼."],["","케이아가 웃음을 거뒀다. 방금 내 목소리와 똑같은 말이 바위 너머에서 되돌아왔다. 북두는 대꾸하지 않고 줄을 짧게 당겼다."]],"steps":[{"kind":"SEARCH","map":null,"title":"밧줄이 지나가는 자리","prompt":"들리는 목소리 대신 연결된 줄과 실제 발자국을 확인한다.","result":"줄은 바위 너머의 그림자를 통과하지 않는다. 네 사람의 실제 위치를 다시 맞췄다.","clues":[{"id":"0","label":"북두의 매듭","text":"매듭은 움직이지 않았다. 줄 끝의 사람이 북두다."},{"id":"1","label":"케이아의 서리","text":"발아래 서리는 여기서 끊긴다. 보이는 몸의 위치와 다르다."},{"id":"2","label":"병사의 발자국","text":"발자국은 넷뿐이다. 새로 걸어온 사람의 흔적은 없다."}]}],"after":[["케이아","내가 다음에 무슨 말을 해도 얼굴부터 보지 마. 줄을 확인하고 대답해."],["북두","너도 남 따라 하는 소리에 장난으로 답하지 마라."],["나","오늘만큼은 두 사람이 서로 못 믿는 게 좀 든든하네."]],"choices":[]},"ISK_L03_B2_072":{"title":"두 자루의 노","before":[["북두","남은 노를 여기로. 멀쩡한 건 두 자루다. 부러진 걸 다시 세지 마."],["짐주인","손이 자꾸 헛돌아서 그래요. 알면서도 하나 더 있으면 좋겠어서…"],["나","나는 멀쩡한 두 자루를 셀게. 없는 거 세다 보면 나도 자꾸 뒤를 보게 돼."],["선원","선장님, 앞에 돌다리! 돛대가 걸립니다!"],["북두","앞의 돌다리 보이지? 돛대가 걸려. 밑의 버팀줄이 굳어서 안 풀린다. 다른 줄은 놔두고 저 고정부만 끊어!"]],"steps":[{"kind":"DESTROY","map":null,"title":"젖어 풀리지 않는 버팀줄","prompt":"돛대를 눕힐 수 있도록 버팀줄의 고정부를 끊는다. 온전한 노 두 자루와 사람을 받치는 줄은 건드리지 않는다.","result":"고정부가 끊어졌다. 북두의 신호에 맞춰 돛대를 낮출 수 있다."}],"after":[["북두","좋아. 이제 내 신호에 맞춰 눕힌다. 힘 빠지면 바로 말해. 배는 고쳐도 네 어깨는 못 갈아 끼워."],["나","알았어. 오늘은 용감한 척 안 할게. 아프면 제일 먼저 소리 지르는 역할은 자신 있어."]],"choices":[]},"ISK_L02_K1_056":{"title":"각청에게 다시 돌아갈 길","before":[],"steps":[],"after":[],"choices":[]},"ISK_L02_K2_062":{"title":"짐꾼 옆에 남긴 표식","before":[],"steps":[],"after":[],"choices":[]},"ISK_L02_AA1_062":{"title":"호두에게 알릴 길","before":[],"steps":[],"after":[],"choices":[]},"ISK_L02_AA2_074":{"title":"천을 풀지 않은 가방","before":[],"steps":[],"after":[],"choices":[]},"ISK_L02_AB1_083":{"title":"반응하지 않은 구슬","before":[],"steps":[],"after":[],"choices":[]},"ISK_L02_AB2_085":{"title":"무너진 가림막","before":[],"steps":[],"after":[],"choices":[]},"ISK_L02_B1_074":{"title":"대답 없는 병사","before":[],"steps":[],"after":[],"choices":[]},"ISK_L02_B2_062":{"title":"북두가 기다리는 바깥길","before":[],"steps":[],"after":[],"choices":[]},"ISK_L04_K1_001":{"title":"들보 아래의 틈","before":[["","바깥을 향해 손을 뻗었다. 큰 들보를 건드릴 수는 없었다. 손끝에 닿는 작은 돌부터 옆으로 밀었다."]],"steps":[{"kind":"DESTROY","map":null,"title":"손을 가로막는 파편","prompt":"몸을 누르는 큰 들보는 피하고 작은 파편을 제거한다.","result":"손을 내밀 틈이 생겼다."}],"after":[["","할 수 있는 일을 끝내고 숨을 골랐다. 이번에는 혼자 대답을 기다리는 시간이 아니었다."]],"choices":[]},"ISK_L04_K2_001":{"title":"이름을 부를 틈","before":[["","세 번 두드리고 기다렸다. 바깥에서도 세 번, 조금 늦은 소리가 돌아왔다. 이번에는 내 이름을 크게 불렀다."]],"steps":[{"kind":"DESTROY","map":null,"title":"목소리가 나갈 틈","prompt":"작은 파편을 치워 바깥과 연결된 틈을 넓힌다.","result":"흙먼지 사이로 바깥빛이 들어왔다."}],"after":[["","할 수 있는 일을 끝내고 숨을 골랐다. 이번에는 혼자 대답을 기다리는 시간이 아니었다."]],"choices":[]},"ISK_L04_AA1_001":{"title":"위에서 떨어지는 돌가루","before":[["호두","저쪽 웃는 입 보지 마. 손은 내가 잡고 있어. 위에서 실제로 떨어지는 돌부터 같이 보자."]],"steps":[{"kind":"SEARCH","map":null,"title":"진짜 구멍이 있는 곳","prompt":"눈앞의 검은 벽 대신 천장과 밧줄을 조사한다.","result":"호두가 떨어지는 돌가루의 방향을 짚었다.","clues":[{"id":"0","label":"천장","text":"돌가루는 입처럼 보이는 틈이 아니라 머리 위에서 떨어진다."},{"id":"1","label":"밧줄","text":"바깥으로 나간 끝이 짧게 당겨진다. 누군가 실제로 잡고 있다."},{"id":"2","label":"호두의 손","text":"호두의 손은 따뜻하다. 벽 속 웃는 입과는 따로 움직인다."}]}],"after":[["","할 수 있는 일을 끝내고 숨을 골랐다. 이번에는 혼자 대답을 기다리는 시간이 아니었다."]],"choices":[]},"ISK_L04_AA2_001":{"title":"움직일 수 있는 곳","before":[["알베도","듣고 있다면 내 손을 봐 줘. 몸을 억지로 움직이려 하지 마. 눈을 움직일 수 있으면 그걸로 충분해."]],"steps":[{"kind":"SEARCH","map":null,"title":"시선으로 전하는 신호","prompt":"움직이지 않는 몸 대신 눈으로 주변의 세 지점을 확인한다.","result":"알베도가 시선의 움직임을 알아봤다. 나를 옮길 준비를 했다.","clues":[{"id":"0","label":"도구 끝","text":"알베도가 내 시선을 따라 도구를 옮긴다."},{"id":"1","label":"가방","text":"구슬이 든 가방을 가리키자 알베도가 내 몸에서 조금 떼어 놓는다."},{"id":"2","label":"바깥길","text":"눈을 바깥길로 돌렸다. 알베도가 어깨를 받쳐 든다."}]}],"after":[["","할 수 있는 일을 끝내고 숨을 골랐다. 이번에는 혼자 대답을 기다리는 시간이 아니었다."]],"choices":[]},"ISK_L04_AB1_001":{"title":"잠긴 문 바깥의 증언","before":[["연비","나야. 운근 씨와 신염이 문을 다시 봤어. 안으로 들어가도 된다는 허가를 기다리는 중이야. 네가 본 곳을 문틈으로 알려 줘."]],"steps":[{"kind":"SEARCH","map":null,"title":"조사실 안에서 남기는 말","prompt":"떠오르는 장면과 실제 손목의 흔적을 따로 확인한다.","result":"진술을 마쳤다. 밖에서 연비가 종이를 넘기는 소리가 들렸다.","clues":[{"id":"0","label":"손목","text":"끈이 닿았던 자국과 구조할 때 긁힌 자국은 다르다."},{"id":"1","label":"문틈","text":"문밖에는 경비가 있다. 혼자 탈출할 길은 아니다."},{"id":"2","label":"무대의 기억","text":"관리인을 끌어낸 손과 닫혀 있던 뒷문을 따로 설명했다."}]}],"after":[["","할 수 있는 일을 끝내고 숨을 골랐다. 이번에는 혼자 대답을 기다리는 시간이 아니었다."]],"choices":[]},"ISK_L04_AB2_001":{"title":"반대편의 손","before":[["다이루크","들리면 벽을 두드려. 네가 있는 쪽을 알고 부숴야 한다."]],"steps":[{"kind":"DESTROY","map":null,"title":"무너진 벽의 안쪽 파편","prompt":"큰 벽은 바깥에서 맡는다. 안쪽의 작은 파편을 제거해 몸을 피할 공간을 만든다.","result":"바깥에서 벽이 움직일 때 몸을 피할 곳이 생겼다."}],"after":[["","할 수 있는 일을 끝내고 숨을 골랐다. 이번에는 혼자 대답을 기다리는 시간이 아니었다."]],"choices":[]},"ISK_L04_B1_001":{"title":"붙잡은 손의 자리","before":[["북두","아직 놓지 마! 케이아, 손 없는 쪽부터 열어! 이쪽은 내가 버틸게!"]],"steps":[{"kind":"DESTROY","map":null,"title":"손 옆에 드러난 돌틀","prompt":"붙잡힌 손과 떨어진 돌틀을 부순다.","result":"돌틀이 깨지며 서리 아래 틈이 벌어졌다."}],"after":[["","할 수 있는 일을 끝내고 숨을 골랐다. 이번에는 혼자 대답을 기다리는 시간이 아니었다."]],"choices":[]},"ISK_L04_B2_001":{"title":"뒤집힌 배의 쇠갈고리","before":[["북두","사람은 전부 우리 배에 있어! 저 아래 소리에 대답하지 마. 걸린 쇠부터 끊는다!"]],"steps":[{"kind":"DESTROY","map":null,"title":"남아 있는 쇠갈고리","prompt":"노와 돛대는 보존한다. 뒤집힌 배의 갈고리를 공격한다.","result":"배 옆을 잡아당기던 힘이 느슨해졌다."}],"after":[["","할 수 있는 일을 끝내고 숨을 골랐다. 이번에는 혼자 대답을 기다리는 시간이 아니었다."]],"choices":[]},"ISK_L04_K1_073":{"title":"보고서에 남은 사람들","before":[["","일행이 다시 모였다. 지금 나눌 이야기는 남은 짐의 수량보다, 함께 겪고 돌아온 일이었다."]],"steps":[],"after":[["연비","고운각 보고에 빠졌던 구조 인원도 확인됐어. 이번에는 이름까지 같이 올릴게."],["감우","네. 원본을 찾는 일도, 사람을 구한 일도 혼자 한 것처럼 적지 않겠습니다."],["나","내가 미끄러진 부분은 빼도 돼. 도와준 사람들 이름은 안 빼고."]],"choices":[["내 몫은 여기까지. 이제 좀 쉬자.","감우|네. 남은 일은 나눠서 하지요."],["다음에 올 때는 아무 일도 없었으면 좋겠어.","연비|그때는 일 때문에 부르지 않을게."]]},"ISK_L04_K2_091":{"title":"되돌려 줄 짐","before":[["","일행이 다시 모였다. 지금 나눌 이야기는 남은 짐의 수량보다, 함께 겪고 돌아온 일이었다."]],"steps":[],"after":[["향릉","자, 이건 기다리지 말고 지금 먹기!"],["행추","보상은 책 한 권으로 받아도 돼?"],["나","그건 밥 주는 사람한테 말해. 난 이름 제대로 물어본 것만으로 오늘 할 일 다 했어."]],"choices":[["내 몫은 여기까지. 이제 좀 쉬자.","향릉|좋아. 남은 일은 나눠서 하자."],["다음에 올 때는 아무 일도 없었으면 좋겠어.","행추|그때는 일 때문에 부르지 않겠네."]]},"ISK_L04_AA1_088":{"title":"돌아온 사람의 등불","before":[["","중운이 끊어진 줄을 내려놓았다. 손바닥에는 밧줄 자국이 남아 있었다. 호두는 그 손을 보고 평소처럼 놀리지 못했다."],["중운","살아 돌아온 건 너희야. 나는 끝을 잡고 있었을 뿐이고."],["호두","그 끝 놓쳤으면 우리가 어디로 갔을지 모르잖아. 오늘은 겸손도 적당히 해."]],"steps":[],"after":[["중운","안쪽에서 들은 목소리는 아직 설명할 수 없어."],["호두","오늘 돌아온 사람을 설명 못 하는 건 아니잖아. 거기부터 쓰면 돼."],["나","그 옆에 중운이 줄 안 놓쳤다는 것도 써 줘. 본인이 쓰면 자랑 같으니까 내가 말할게."]],"choices":[["내 몫은 여기까지. 이제 좀 쉬자.","호두|좋아. 남은 일은 나눠서 하자."],["다음에 올 때는 아무 일도 없었으면 좋겠어.","중운|그때는 일 때문에 부르지 않을게."]]},"ISK_L04_AA2_098":{"title":"결과가 아닌 안부","before":[["","백출은 알베도의 기록을 옆으로 밀고 내 얼굴부터 보았다."],["백출","연구 이야기는 조금 뒤에 하죠. 지금 불편한 곳부터 말씀해 주세요."],["나","배가 고파. 어제보다는 혼자 걸을 만하고. 이 정도면 중요한 보고지?"]],"steps":[],"after":[["백출","연구 결과보다 반가운 소식이네요. 식사는 거르지 마세요."],["알베도","기록에도 그렇게 남겨 둘게."],["나","배고프다는 것까지? 나중에 읽는 사람은 내가 계속 밥만 찾았다고 하겠네."]],"choices":[["내 몫은 여기까지. 이제 좀 쉬자.","백출|좋습니다. 남은 일은 나눠서 하죠."],["다음에 올 때는 아무 일도 없었으면 좋겠어.","알베도|그때는 일 때문에 부르지 않을게."]]},"ISK_L04_AB1_121":{"title":"다시 열 무대","before":[["","운근은 부러진 무대 조각을 덮었다. 신염은 옆에 앉아 악기를 무릎에 놓고도 줄을 건드리지 않았다."],["운근","오늘 일을 극으로 만들고 싶지는 않아요. 돌아오지 못한 분은 우리 결말을 위해 계셨던 게 아니니까요."],["신염","그럼 오늘은 안 치자. 다음 공연 날짜도 나중에 잡고."],["나","응. 나도 여기 좀 앉아 있을게. 말 안 해도 괜찮지?"]],"steps":[],"after":[["운근","괜찮아요. 아까는 사람을 붙잡을 손부터 찾았는데, 지금은 그냥 옆에 계셔 주시면 돼요."],["신염","다음에 노래 부를 때는 내가 앞줄에 있을게. 문은 다른 사람한테 맡기고."],["연비","그땐 나도 일하러 온 사람처럼 서 있지 않을게."],["","해가 기울 무렵, 운근은 접힌 대본을 품에 넣었다. 이번에는 무대가 아닌 부두 쪽으로 걸었다."]],"choices":[["내 몫은 여기까지. 이제 좀 쉬자.","운근|네, 남은 일은 나눠서 해요."],["다음에 올 때는 아무 일도 없었으면 좋겠어.","신염|그때는 일 때문에 부르지 않을게."]]},"ISK_L04_AB2_115":{"title":"끝나지 않은 운송표","before":[["연비","화물 주인에게 돌려줄 원본은 챙겼어. 남은 조사는 내가 이어 갈게."],["야란","받으러 오는 사람은 내가 보지. 이번에는 출입 시각도 남기고."],["다이루크","위험하면 연락해. 혼자 쫓는 건 그다음이다."],["나","그 말 셋 다 자기한테도 해 주면 안 돼? 오늘은 내가 제일 안 무리했어."]],"steps":[],"after":[["연비","맞는 말이야. 서명할래? 내가 간단하게 적어 줄게."],["야란","벌써 편이 바뀌었네."],["다이루크","연락처부터 남기지."],["나","좋아. 이렇게 말 많이 하게 만들었으면 오늘은 내가 이긴 거다."]],"choices":[["내 몫은 여기까지. 이제 좀 쉬자.","연비|좋아. 남은 일은 나눠서 하자."],["다음에 올 때는 아무 일도 없었으면 좋겠어.","야란|그때는 일 때문에 부르지 않을게."]]},"ISK_L04_B1_084":{"title":"편지의 도착지","before":[["","행추와 중운이 찾아온 것은 구조 소식을 듣고서였다. 행추는 질문을 꺼내려다가 케이아의 팔에 감긴 붕대를 보고 입을 다물었다."],["중운","이번만큼은 듣자마자 모험담이라고 하지 마."],["행추","그런 말 안 해. 필요한 사람에게 무사하다는 소식부터 전하러 온 거야."],["행추","아, 너와는 처음이네. 비운 상회의 행추야. 이쪽은 중운이고."],["중운","중운이야. 퇴마사고. 다친 사람이 없다니 다행이다."]],"steps":[],"after":[["북두","병사 가족에게 먼저 알려 줘. 괜찮다는 말도 본인 목소리로 듣게 데려와 주고."],["케이아","소문이 내 것보다 빨리 돌아다니는 날이군. 오늘은 경쟁할 생각 없어."],["나","내 소문은 조금만 늦춰 줘. 내가 돌아가서 설명할 체력부터 되찾게."]],"choices":[["내 몫은 여기까지. 이제 좀 쉬자.","행추|좋네. 남은 일은 나눠서 하세."],["다음에 올 때는 아무 일도 없었으면 좋겠어.","중운|그때는 일 때문에 부르지 않을게."]]},"ISK_L04_B2_074":{"title":"여덟 명의 귀항표","before":[["","부두에서 응광과 감우가 생환자를 기다리고 있었다. 북두는 배를 묶기도 전에 손가락을 폈다."],["북두","사람은 여덟. 돌아온 사람도 여덟. 손실 보고 첫 줄은 그걸로 해."],["감우","적었습니다. 선장님이 배에서 내리시기 전에도 두 번 말씀하셔서요."],["응광","군옥각을 잃고도 보고서를 읽게 될 줄은 몰랐네요. 그래도 그 첫 줄은 반갑군요."],["나","네 번째는 내가 말해도 돼? 그 숫자는 질리도록 확인하고 싶어."]],"steps":[],"after":[["응광","당신답네요. 배를 잃어도 사람 숫자부터 맞추고."],["북두","배도 아까워. 그러니까 다음 수리비 얘기는 깎지 말고 들어."],["나","둘이 이제 제대로 싸우는 것 같아서 좀 안심했어."],["감우","…그 말은 보고서에 넣지 않겠습니다."]],"choices":[["내 몫은 여기까지. 이제 좀 쉬자.","북두|좋아. 남은 일은 나눠서 하자."],["다음에 올 때는 아무 일도 없었으면 좋겠어.","응광|그때는 일 때문에 부르지 않겠어요."]]},"ISK_L03_AB1_060":{"title":"사건 전의 뒷문","before":[["","공연을 앞두고 신염이 뒤편 통로에서 지렛대를 들고 나왔다. 운근은 그걸 치우지 말고 출구 옆에 두어 달라고 했다."],["신염","공연 준비라더니 탈출로부터 챙기네. 오늘 관객들 상태가 많이 안 좋아?"],["운근","병사분이 아직 부르지도 않은 구절을 알고 계셨어요. 공연은 제가 책임질게요. 대신 뒤는 같이 봐 주시겠어요?"],["연비","각청이 진술을 맡겼어. 공연이 시작되기 전의 상태를 먼저 적어 두자. 나중에 다들 다른 말을 하면 비교할 게 있어야 해."],["신염","참, 너는 처음 보네. 난 신염. 오늘 무대 반주를 맡았어."],["나","그러면 난 문부터 볼게. 무대 받치는 건 아까 했으니까, 이번에는 사람들이 나갈 곳을 맡을래."],["신염","좋아. 내가 반대편을 볼게. 여기까지 와서 가만히 박수만 치는 건 적성에 안 맞거든."]],"steps":[{"kind":"SEARCH","map":null,"title":"열린 문과 금이 간 계단","prompt":"공연 전에 출구와 구조 도구의 위치를 확인한다.","result":"신염은 바깥 출구를, 운근은 무대 안쪽을 맡았다. 같은 문을 서로 다른 쪽에서 본 시각을 연비가 적었다.","clues":[{"id":"0","label":"뒷문 빗장","text":"문은 안쪽에서 잠근다. 지금은 열려 있고, 바깥에 신염이 서 있다."},{"id":"1","label":"금이 간 계단","text":"각청이 표시한 금이다. 무너지면 위에서 뛰어내리는 대신 옆에서 들어야 한다."},{"id":"2","label":"출구의 지렛대","text":"관리인이 바퀴를 들 때 쓰던 도구다. 받침목과 함께 손이 닿는 곳에 놓았다."}]}],"after":[["운근","끝나면 신염 씨 연주도 들려주세요. 오늘은 두 사람 몫을 혼자 하려니 조금 떨리네요."],["신염","넌 시작할 때만 그래. 노래 나오면 내가 옆에서 손 흔들어도 못 보잖아."],["나","나는 흔들면 볼게. 오늘 내 일은 사람 놓치지 않는 거니까."]],"choices":[]}},"sceneEdits":[{"quest":"Q_ISK_LIYUE_01","scene":"K_DEPART","speaker":"진","opening":"진이 성문 앞에서 지도를 펼쳤다. 리월의 신이라면 돌아갈 길을 알까. 기대부터 하고 싶었지만, 우선 오늘 저녁까지 걸어갈 체력이 있는지가 문제였다.","beat":"길을 안다고 무리해도 되는 건 아니야. 위험하면 돌아와. 네가 떠난다고 몬드의 문까지 닫히는 건 아니니까.","closing":"나는 지도를 받아 들었다. “그 말, 돌아왔을 때도 해 줘. 빈손이면 좀 민망할 것 같거든.” 진이 웃으며 남쪽 길을 가리켰다."},{"quest":"Q_ISK_LIYUE_01","scene":"K_WANGSHU","speaker":"소","opening":"망서 객잔이 보이자 배부터 울었다. 그런데 승강기에서 짐이 쏟아졌다. 밥 생각을 접고 달려가자, 난간에 매달린 짐꾼이 손을 내밀었다.","beat":"네 주변에 낯선 기운이 있다. 내 눈을 피한다고 없어질 것은 아니야. 하지만 지금 떨어지는 저 사람과는 다른 문제다. 먼저 구해라.","closing":"짐꾼을 끌어올린 뒤에야 손이 떨렸다. 소는 더 캐묻지 않고 사라졌다. 나는 객잔 종업원에게 물었다. “밥 주문하면서 방금 일까지 물어봐도 될까요?”"},{"quest":"Q_ISK_LIYUE_01","scene":"K_GUILI_MORNING","speaker":"짐꾼","opening":"아침 길에 어제의 짐꾼을 다시 만났다. 그는 내가 구한 짐보다 무거운 포대를 등에 얹고 있었다. 돕겠다고 손을 뻗자 먼저 내 신발부터 내려다봤다.","beat":"그 신발로 내 짐까지 들면 리월에는 발바닥만 도착하겠네. 옆에서 길이나 봐줘. 수레 오면 소리 지르고.","closing":"짐은 그가, 길은 내가 살폈다. 어제 소에게 들은 말은 아직 무서웠지만, 누군가와 같은 속도로 걷는 동안은 조금 덜했다."},{"quest":"Q_ISK_LIYUE_01","scene":"K_HARBOR_GATE","speaker":"각청","opening":"리월항 입구는 수레와 사람으로 막혀 있었다. 각청은 차단선 옆에서 직접 짐을 옮기고 있었다. 나는 줄을 세우는 사람이 가장 바빠 보이는 이상한 광경을 구경하다 그녀와 눈이 마주쳤다.","beat":"구경할 힘은 남았나 보네. 그 줄 좀 잡아줘. 이야기는 사람들이 그늘로 옮겨 간 다음에 듣겠어.","closing":"그늘막을 세우고 나니 각청이 빈 의자를 내줬다. 낯선 기운을 털어놓을지, 짐이 오간 흔적부터 보여 줄지 정해야 했다. 이번에는 아는 척부터 하지 않기로 했다."},{"quest":"Q_ISK_LIYUE_01","scene":"K1_WITNESS","speaker":"각청","opening":"나는 소에게 들은 경고부터 꺼냈다. 입으로 말하니 더 수상했다. 스스로도 의심스러운 사람을 각청은 비웃지 않고 끝까지 바라봤다.","beat":"네가 먼저 알리러 왔다는 건 적어 두겠어. 그렇다고 내 판단까지 대신 정하지는 마. 본 것과 짐작한 것을 나눠서 얘기해 줘.","closing":"조사는 별도 자리에서 이어졌다. 각청은 자리를 뜨기 전에 물을 놓아 주었다. 붙잡혔다고 하기에는 친절했고, 안심하기에는 모르는 것이 너무 많았다."},{"quest":"Q_ISK_LIYUE_01","scene":"K2_TRANSFER","speaker":"짐꾼","opening":"같은 포대를 두 번 검사하는 병사 옆에서 짐꾼이 한숨을 쉬었다. 내가 밧줄을 잡자 그는 허리를 펴며 웃었다. “도움은 받아도 허리는 빌려주지 마.”","beat":"사람이 기억을 못 하면 짐이라도 가만있어야지. 아까 저쪽에 놓은 포대가 왜 여기 있나, 그것부터 같이 보세.","closing":"각청이 포대를 봉하고 운송 기록을 따로 챙겼다. 짐꾼은 내 몫의 자리를 비워 줬다. 세상 비밀을 밝히러 왔는데 우선 짐을 제대로 세는 일이 내 일이 되었다."},{"quest":"Q_ISK_LIYUE_01","scene":"성문 뒤에 남긴 이름","speaker":"","opening":"몬드의 다리를 건너며 가방을 고쳐 멨다. 구슬과 그 안의 유해는 여전히 내 몫이었다. 벤티가 알려 준 이름, 모락스. 사람을 만나러 가는 것처럼 신의 이름을 되뇌었다.","beat":"","closing":"성문을 다시 돌아보지는 않았다. 대신 주머니가 제대로 잠겼는지 한 번 더 확인했다. 신에게 물을 질문보다 당장 잃어버리면 안 되는 물건이 먼저였다."},{"quest":"Q_ISK_LIYUE_01","scene":"바람을 붙잡는 일부터","speaker":"호두","opening":"남쪽 길에서 수레가 비탈로 미끄러졌다. 검은 모자의 소녀가 짐을 받쳤고, 나는 수레꾼의 옷자락을 바퀴에서 빼냈다. 첫 리월 사람과의 인사는 서로 욕먹을 틈도 없는 상태에서 시작됐다.","beat":"왕생당 당주, 호두! 인사는 이만큼 하고 반대쪽을 잡아 줘. 손님보다 수레가 먼저 넘어오면 나도 곤란하거든.","closing":"수레가 멎자 호두는 짐꾼의 무릎부터 확인했다. 장난스러운 말투와 손놀림은 달랐다. 나는 숨을 고르며 말했다. “다음 인사는 평평한 곳에서 하자.”"},{"quest":"Q_ISK_LIYUE_01","scene":"누구를 위한 천인가","speaker":"호두","opening":"호두는 흙 묻은 가림천을 털어 접었다. 왕생당이 장례를 맡는 곳이라는 설명을 듣고 나는 가방 쪽으로 손을 옮겼다. 호두의 눈이 그 움직임을 놓치지 않았다.","beat":"살아 있는 사람도 얼굴을 가릴 일은 있지. 그래도 네가 데려온 분 이야기를 할 거라면, 농담은 잠깐 접을게.","closing":"구슬 안의 유해를 보여 줄지, 감싼 채 사정을 먼저 말할지 물었다. 호두는 손을 내밀지 않고 기다렸다. 그래서 오히려 말을 꺼낼 용기가 났다."},{"quest":"Q_ISK_LIYUE_01","scene":"2AA1 · 보이는 것만, 허락한 만큼","speaker":"호두","opening":"흔들리지 않는 판 위에 구슬을 놓았다. 호두는 장갑을 끼고 내 맞은편에 앉았다. 아까의 장난은 사라졌지만, 나를 이상한 물건 취급하는 눈빛도 없었다.","beat":"누군지 모른다고 함부로 이름을 붙일 수는 없어. 네가 여기까지 데려왔으니, 어디서 만났는지부터 들려줘.","closing":"호두는 확인한 것만 따로 적었다. 내가 다시 천을 덮자 끝이 풀리지 않게 끈을 고쳐 줬다. “들고 온 사람 손까지 다치면 일만 늘어나잖아.” 그제야 나도 조금 웃었다."},{"quest":"Q_ISK_LIYUE_01","scene":"2AA1 · 옥형 앞의 두 증언","speaker":"각청","opening":"차단선 앞에서 호두가 왕생당의 일을 설명하고, 나는 구슬을 발견한 일을 설명했다. 두 이야기를 한꺼번에 하다가 서로 말을 끊었다. 각청이 손가락 하나를 들어 우리를 멈췄다.","beat":"한 명씩. 당주가 먼저 말하고, 네가 빠진 부분을 덧붙여. 두 사람이 동시에 무죄를 주장하면 내가 적을 수가 없잖아.","closing":"호두가 입을 다물자 내가 괜히 미안해졌다. 각청은 구슬을 빼앗지 않았다. 대신 다시 만날 장소를 정했다. 리월에서 처음 생긴 약속치고는 제법 무거웠다."},{"quest":"Q_ISK_LIYUE_01","scene":"2AA2 · 감싼 채로 남기는 이름","speaker":"호두","opening":"나는 천을 풀지 않은 채 구슬을 발견한 경위를 말했다. 접수대 너머의 남자가 가방을 너무 오래 보고 있었다. 호두는 말없이 내 가방이 보이지 않는 쪽으로 자리를 바꿨다.","beat":"오늘 안 보여 준다고 내일도 못 보는 건 아니지. 서두르지 말자. 저쪽이 더 궁금해하는 얼굴이라서 말이야.","closing":"내용을 정리해 접수하자 호두가 표를 내 손에 쥐여 줬다. “이건 잃어버리지 마. 네 얘기 들어 줬다는 증거니까.” 나는 구슬보다 종이를 먼저 챙겨 넣었다."},{"quest":"Q_ISK_LIYUE_01","scene":"2AA2 · 접수했다고 열리지는 않는 문","speaker":"각청","opening":"각청은 접수 기록을 읽고도 내게 같은 질문을 했다. 짜증부터 내려다가, 그녀가 기록 끝의 엉뚱한 표현에 밑줄을 긋는 것을 보았다. 내가 한 말과 조금 달랐다.","beat":"불편하겠지만 네 입으로 한 번만 더 말해 줘. 담당자가 잘못 알아들었으면 지금 고쳐야 해. 나중에는 이 종이가 네 말보다 오래 남아.","closing":"틀린 문장을 고친 뒤 기다릴 자리를 정했다. 호두가 내 옆에 앉으며 물었다. “배는 고프지?” 수상한 구슬 이야기보다 그 질문에 더 빨리 고개가 끄덕여졌다."},{"quest":"Q_ISK_LIYUE_01","scene":"ISK_L01_AB_S_01","speaker":"다이루크","opening":"다이루크는 가방 끈이 풀리지 않는지 확인했다. 각청은 길을 보고 있었다. 앨리스가 맡긴 구슬은 내 품에, 리월로 가는 길은 그녀 손에 있었다.","beat":"급한 일이 생기면 연락해. 도움을 청하기 전에 네가 얼마나 버틸 수 있는지 시험할 필요는 없다.","closing":"나는 고개를 끄덕이고 각청을 따라 다리를 건넜다. “길은 부탁할게. 나는 짐 잃어버리지 않는 쪽을 맡고.” 각청이 가방을 흘끗 보더니 매듭 하나를 더 조였다."},{"quest":"Q_ISK_LIYUE_01","scene":"ISK_L01_AB_S_02","speaker":"각청","opening":"각청이 갑자기 멈췄다. 쉴 시간인 줄 알고 좋아한 나는 곧 비탈 아래의 약초꾼을 봤다. 그녀가 내게 짐을 던지고 무릎을 꿇자, 나는 밧줄부터 찾아 꺼냈다.","beat":"그 줄을 내 허리에 묶어. 사람 하나를 더 구하겠다고 둘 다 굴러떨어질 필요는 없으니까. 꽉 잡을 수 있지?","closing":"약초꾼을 끌어올린 뒤 각청이 내 손바닥을 확인했다. “다음엔 쉬려고 멈출게.” 나는 땅바닥에 앉아 대답했다. “그 약속은 꼭 지켜 줘.”"},{"quest":"Q_ISK_LIYUE_01","scene":"ISK_L01_AB_S_03","speaker":"각청","opening":"숙영지의 아침은 생각보다 추웠다. 나는 따뜻한 물컵을 놓지 못한 채 각청이 연락 문서를 묶는 모습을 봤다. 그녀가 내 몫의 접견 확인서를 건넸다.","beat":"나를 찾을 때 보여 줘. 통행증은 아니야. 네가 이 종이 한 장으로 모든 문을 열려고 하면 나도 난처해져.","closing":"“만능 열쇠인 줄 알았는데.” 각청은 웃지 않으려다 실패했다. 종이를 젖지 않는 곳에 넣고, 우리는 짐 행렬을 따라 귀리 평원으로 나섰다."},{"quest":"Q_ISK_LIYUE_01","scene":"ISK_L01_AB_S_04","speaker":"각청","opening":"항구가 가까워질수록 길은 더 막혔다. 앞줄의 상인은 내가 각청과 함께 왔다는 이유만으로 차례를 양보하려 했다. 나는 괜찮다고 손사래를 쳤다.","beat":"그대로 기다려. 내가 데리고 왔다고 네가 해야 할 확인까지 없어지는 건 아니야. 대신 잘못 기다리는 일은 없게 할게.","closing":"접견 확인은 받았지만 도시 안으로 들어가는 일은 따로였다. 나는 종이를 접으며 말했다. “여기까지 왔는데 문턱이 마지막 오르막이네.” 각청이 빈 작업대를 가리켰다. 우선 앉을 곳은 있었다."},{"quest":"Q_ISK_LIYUE_01","scene":"ISK_L01_AB_S_05","speaker":"각청","opening":"이미 넘겼다는 상자와 받지 못했다는 기록이 같은 탁자에 놓였다. 병사는 그 사이 몇 분을 기억하지 못했다. 소리치는 상인에게서 눈을 돌리자 각청이 내 선택을 기다리고 있었다.","beat":"병사의 이야기를 들을까, 옮겨진 짐을 따라갈까? 어느 쪽을 고르든 나머지는 그대로 보존해 둘게. 양쪽을 쫓다가 둘 다 놓치지는 말자.","closing":"나는 한쪽을 택했다. 이상한 일을 겪은 사람이 나 하나는 아닐지도 몰랐다. 이번에는 내 기억을 증명하는 것보다, 저 사람이 잃어버린 시간을 찾고 싶었다."},{"quest":"Q_ISK_LIYUE_01","scene":"ISK_L01_AB_S_AB1_01","speaker":"각청","opening":"초소 뒤의 병사는 질문보다 시선을 더 무서워했다. 나는 맞은편 의자 대신 옆의 빈 상자에 앉았다. 기억이 안 나냐고 다그치기 전에 내가 누구인지부터 말했다.","beat":"떠오르는 부분만 말해도 돼. 그 앞뒤를 맞추는 건 우리가 할 일이야. 네가 억지로 채워 넣을 일이 아니고.","closing":"면담 중 가림틀이 넘어졌다. 모두 빠져나온 뒤 병사는 내 팔을 당긴 일을 기억하지 못했다. 내 팔에는 손자국이 남아 있었다. 각청은 그 자국을 보고 질문을 멈췄다."},{"quest":"Q_ISK_LIYUE_01","scene":"ISK_L01_AB_S_AB1_02","speaker":"교대 병사","opening":"기록을 읽던 병사는 한 문장 앞에서 펜을 멈췄다. 자기 이름으로 적혀 있지만 자기 말 같지 않다고 했다. 나는 그 문장을 지우지 않고 옆에 표시했다.","beat":"분명 내가 한 일인데 남이 얘기해 줘야 알겠어요. 내일 또 기억이 없으면, 오늘 말한 것도 없던 일이 되는 겁니까?","closing":"“그러면 내가 오늘 들었다고 말할게.” 거창한 약속은 못 했다. 병사는 그 말에 처음으로 내 얼굴을 똑바로 봤다."},{"quest":"Q_ISK_LIYUE_01","scene":"ISK_L01_AB_S_AB1_03","speaker":"각청","opening":"같은 자리에서 서로 다른 기억이 나왔다. 나는 어느 쪽이 맞는지 얼른 결정하고 싶었다. 각청은 내 손에서 기록지를 받아 두 장을 나란히 놓았다.","beat":"한 장이 틀렸다고 정하면 편하겠지. 하지만 그 편한 답 때문에 사람을 놓칠 수도 있어. 조금만 더 확인하자.","closing":"사람들의 말을 따로 남기고 초소 주변의 흔적을 살폈다. 누구 하나를 거짓말쟁이로 만들지 않아도, 같은 일이라고 보기 어려운 차이는 남았다."},{"quest":"Q_ISK_LIYUE_01","scene":"ISK_L01_AB_S_AB1_04","speaker":"각청","opening":"면담이 끝나자 다리가 뒤늦게 아팠다. 내가 의자에 주저앉는 모습을 본 각청이 아직 질문이 남았느냐고 물었다. 나는 물부터 남았으면 좋겠다고 했다.","beat":"그건 있어. 오늘은 여기까지 하자. 네가 쓰러지면 조사할 사람이 한 명 더 늘어나니까.","closing":"각청이 물을 내밀었다. 나는 컵을 받고 다음 만남을 정했다. 기다리는 동안 무엇을 할지는 내가 정할 수 있었다. 이번에는 억지로 도움이 되는 척하지 않아도 됐다."},{"quest":"Q_ISK_LIYUE_01","scene":"ISK_L01_AB_S_AB2_01","speaker":"운송인","opening":"상자는 접수대를 지났는데 받았다는 사람이 없었다. 운송인은 빈 수레를 발로 툭 건드렸다. 내가 바퀴에 묻은 진흙을 가리키자 그가 허리를 숙였다.","beat":"그 길은 내가 안 갔는데. 수레가 혼자 다녀온 건 아닐 테고, 누가 내 수레를 끌었는지부터 찾아봅시다.","closing":"우리는 상자 이름 대신 바퀴 자국을 따라갔다. 각청은 서로 다르게 적힌 인계 시각을 챙겼다. 종이 속 말다툼이 실제 길 위의 흔적으로 바뀌었다."},{"quest":"Q_ISK_LIYUE_01","scene":"ISK_L01_AB_S_AB2_02","speaker":"각청","opening":"창고와 접수대를 오가는 동안 각청의 질문은 점점 짧아졌다. 상인은 대금부터, 운송인은 자기 짐부터 걱정했다. 나는 둘 사이에서 빈 수레가 더 가벼워 보인다고 했다.","beat":"농담할 여유는 있네. 그럼 그 수레가 마지막으로 무거웠던 곳까지 안내해 줘. 거기부터는 내가 묻겠어.","closing":"마지막으로 짐을 본 사람과 보지 못한 사람을 나눠 확인했다. 누구의 체면을 먼저 세울지 싸우는 대신, 사라진 물건을 찾는 일에 다시 손이 움직였다."},{"quest":"Q_ISK_LIYUE_01","scene":"ISK_L01_AB_S_AB2_03","speaker":"운송인","opening":"표식은 같은데 포장 상태가 달랐다. 운송인은 내가 자루를 들기 전에 밑을 받쳐 줬다. 나는 모르는 척 들어 올렸다가 허리를 다칠 뻔했다고 털어놓았다.","beat":"그걸 이제 말하면 어떡해요. 짐은 둘이 들어도 물건값 안 줄어요. 반대쪽 잡아요.","closing":"우리는 남은 짐을 함께 펼쳤다. 각청은 달라진 포장과 기록을 한 묶음으로 남겼다. 없어지지 않은 것들 덕분에, 무엇이 없어졌는지가 드러났다."},{"quest":"Q_ISK_LIYUE_01","scene":"ISK_L01_AB_S_AB2_04","speaker":"각청","opening":"조사를 돕겠다고 한 뒤에야 기다릴 시간이 길다는 것을 실감했다. 나는 빈 상자 뚜껑을 의자처럼 놓다가 각청에게 들켰다.","beat":"그건 앉는 순간 부서져. 작업대 옆에 의자 가져다 놨어. 도와주러 온 사람한테 허리 치료비까지 물릴 생각은 없어.","closing":"의자에 앉아 구슬이 든 가방을 끌어안았다. 각청은 곧 소식을 가져오겠다고 했다. 나는 그동안 할 수 있는 일부터 적었다. 첫 줄은 식사였다."},{"quest":"Q_ISK_LIYUE_01","scene":"ISK_L01_S_B_01","speaker":"알베도","opening":"알베도는 구슬을 보기에 앞서 내 손가락이 잘 움직이는지 확인했다. 창밖에서는 사람들이 저녁거리를 사고 있었다. 이상한 물건을 가졌어도 저녁은 먹어야 한다는 사실이 새삼 다행이었다.","beat":"이것만 생각하느라 네 하루를 전부 쓰지는 마. 당장 모르는 것은 적어 둘 수 있어. 네가 다치는 건 기록만 해 두고 끝낼 수 없지만.","closing":"구슬을 감싸 가방에 넣었다. 나는 길드 안내판을 가리켰다. “그럼 우선 여행비부터 구해 볼게. 모르는 물건도 모라는 안 주더라고.”"},{"quest":"Q_ISK_LIYUE_01","scene":"ISK_L01_S_B_02","speaker":"캐서린","opening":"길드에는 리월행 물자 행렬의 동행자를 구하는 공고가 붙어 있었다. 길도 모르고 여행비도 넉넉하지 않은 내게는 반가운 소식이었다.","beat":"별과 심연을 향해! 길 안내와 식사를 함께 구하는 셈이네. 대신 짐 옮기는 일은 거들어야 해. 할 수 있는 만큼부터 담당자와 정해 봐.","closing":"알베도에게 나중에 소식을 보내겠다고 했다. 구슬 이야기가 아니어도 좋다는 대답을 듣고, 나는 괜히 맛있는 것 하나는 찾아야겠다고 생각했다."},{"quest":"Q_ISK_LIYUE_01","scene":"ISK_L01_S_B_03","speaker":"북두","opening":"물자 행렬이 리월의 갈대밭에 닿았을 때, 앞쪽에서 시원한 웃음소리가 들렸다. 북두는 짐을 든 사람부터 쉬게 하고 나중에 온 내 이름을 물었다.","beat":"난 북두, 남십자 함대의 선장이야. 뱃멀미는 나중에 물어보고, 지금은 수레멀미부터 보자. 얼굴이 왜 그렇게 구겨졌어?","closing":"“도와주러 왔는데 짐보다 제가 더 흔들립니다.” 북두는 웃으며 가벼운 줄뭉치를 내줬다. 못 하는 걸 숨기는 것보다 자기 몫을 찾는 편이 빨랐다."},{"quest":"Q_ISK_LIYUE_01","scene":"ISK_L01_S_B_04","speaker":"북두","opening":"목책 앞에서 인계 말이 바뀌었다. 이미 맡긴 짐을 다시 내라는 요구에 선원들이 목소리를 높였다. 북두는 앞에 나서기 전에 사람들 사이의 수레부터 밀어냈다.","beat":"싸우더라도 다친 사람은 만들지 말자. 거기, 상관을 불러. 우리 쪽 설명은 내가 할 테니까, 이 친구한테 같은 질문을 쏟아붓지는 말고.","closing":"그 틈에 나는 포장을 받치고 있던 판자를 고정했다. 큰 소리보다 먼저 할 일이 있었다. 북두는 돌아와 내 어깨를 두드리고 각청을 불렀다."},{"quest":"Q_ISK_LIYUE_01","scene":"ISK_L01_S_B_05","speaker":"각청","opening":"각청과 북두가 인계 기록을 맞추는 동안 나는 말없이 자루를 세었다. 숫자는 맞는데 마지막 자루를 내려놓은 사람이 달랐다. 잘못 센 줄 알고 다시 세어도 같았다.","beat":"숫자를 세 번 맞췄으면 이제 사람을 봐야지. 네가 직접 본 사람은 누구야? 다른 사람이 알려 준 이름 말고.","closing":"병사를 만나 기억을 확인할지, 물자를 따라 이동을 확인할지 길이 갈렸다. 북두는 어느 쪽이든 짐과 사람을 혼자 떠맡지 말라고 했다. 나는 그 말을 약속으로 받아 뒀다."},{"quest":"Q_ISK_LIYUE_01","scene":"ISK_L01_S_B_06","speaker":"북두","opening":"병사는 북두와 말을 나눴다는 사실부터 확신하지 못했다. 북두는 처음부터 다시 자기 이름을 댔다. 나도 따라서 인사하자 병사가 당황한 얼굴로 웃었다.","beat":"좋아, 그럼 지금 만난 것부터는 셋이 기억하는 거네. 아까 일이 안 떠오른다고 지금까지 혼자 있을 필요는 없지.","closing":"나는 구슬을 품고 리월에 온 사정을 말했다. 북두는 물건보다 내 얼굴을 봤다. “그것도 중요하겠지만, 여기까지 온 사람 이야기도 들을 만하네.”"},{"quest":"Q_ISK_LIYUE_01","scene":"ISK_L01_S_B_07","speaker":"북두","opening":"포장 둘의 위치를 확인하다 보니 어느새 상인들 사이에 끼었다. 모두 내 대답부터 기다렸다. 나는 잠깐만 시간을 달라고 말하고 북두를 찾았다.","beat":"잘했어. 모르면 멈추는 것도 일이야. 빨리 대답하라는 사람한테 꼭 틀린 답까지 줘야 하는 건 아니잖아.","closing":"다시 살핀 포장에는 옮긴 흔적이 남아 있었다. 북두와 나는 그 짐을 따로 묶었다. 쓸모 있는 사람이 되려고 허둥대는 것보다, 함께 확인하는 쪽이 훨씬 든든했다."}]};
